-- Create "media" table
CREATE TABLE "media" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "uuid" character varying(36) NOT NULL DEFAULT (uuidv7())::text,
  "model_type" character varying(255) NOT NULL,
  "model_id" character varying(255) NOT NULL,
  "collection_name" character varying(255) NOT NULL,
  "disk" character varying(255) NOT NULL,
  "name" character varying(255) NOT NULL,
  "file_name" character varying(255) NOT NULL,
  "mime_type" character varying(255) NOT NULL,
  "conversions_disk" character varying(255) NULL,
  "size" bigint NOT NULL DEFAULT 0,
  "conversion_status" character varying(50) NOT NULL DEFAULT 'completed',
  "order_column" integer NULL,
  "manipulations" jsonb NULL,
  "custom_properties" jsonb NULL,
  "generated_conversions" jsonb NOT NULL DEFAULT '{}',
  "responsive_images" jsonb NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
-- Create index "idx_media_collection" to table: "media"
CREATE INDEX "idx_media_collection" ON "media" ("collection_name");
-- Create index "idx_media_model" to table: "media"
CREATE INDEX "idx_media_model" ON "media" ("model_type", "model_id");
-- Create index "idx_media_uuid" to table: "media"
CREATE UNIQUE INDEX "idx_media_uuid" ON "media" ("uuid");
-- Create "notifications" table
CREATE TABLE "notifications" (
  "id" uuid NOT NULL DEFAULT uuidv7(),
  "notifiable_type" character varying(255) NOT NULL,
  "notifiable_id" character varying(255) NOT NULL,
  "type" character varying(255) NOT NULL,
  "data" text NOT NULL,
  "read_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz NULL,
  PRIMARY KEY ("id")
);
-- Create index "idx_notifiable" to table: "notifications"
CREATE INDEX "idx_notifiable" ON "notifications" ("notifiable_type", "notifiable_id");
-- Create index "idx_notifications_deleted_at" to table: "notifications"
CREATE INDEX "idx_notifications_deleted_at" ON "notifications" ("deleted_at");
-- Create index "idx_notifications_read_at" to table: "notifications"
CREATE INDEX "idx_notifications_read_at" ON "notifications" ("read_at");
